<script setup lang="ts">
import {onMounted,ref} from 'vue'
import Request from '../../../api/Request'
const base='api/v1/keys',busy=ref(false),error=ref(''),receipt=ref<any>(null),batch=ref<any>(null),batches=ref<any[]>([]),exports=ref<any[]>([]),keys=ref<any[]>([]),total=ref(0),page=ref(1),key=ref<any>(null),keyHistory=ref<any[]>([])
const draft=ref({type:0,face:1,count:1,faceName:'',reason:''}),frozen=ref<any>(null),reason=ref(''),keyFrozen=ref<any>(null),keyReceipt=ref<any>(null),exportReason=ref(''),exportFrozen=ref<any>(null),exportReceipt=ref<any>(null),lookup=ref(''),exactCode=ref('')
const uuid=()=>crypto.randomUUID()
async function failure(e:any){if(e.response?.data instanceof Blob){try{return JSON.parse(await e.response.data.text()).message||e.message}catch{return e.message}}return e.response?.data?.message||e.message||'CDK管理失败'}
const terminal=(r:any)=>r&&['PREVIEWED','PERSISTED','NOT_APPLIED','NO_CHANGE'].includes(r.state)
function remember(kind:string,id:string){sessionStorage.setItem('cdk-inventory-'+kind,id)}
function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';return action().catch(async e=>{error.value=await failure(e)}).finally(()=>{busy.value=false})}
async function load(){batches.value=(await Request.get(`${base}/batches/history`)).data;exports.value=(await Request.get(`${base}/exports/history`)).data;await query()}
async function query(){const q={page:page.value,pageSize:20,...(exactCode.value?{content:exactCode.value}:{})};const r=(await Request.post(`${base}/query`,q)).data;keys.value=r.list;total.value=Number(r.totalSize)}
function prepare(){return run(async()=>{if(!frozen.value){const payload={...draft.value,faceName:draft.value.faceName||null};const validation=(await Request.post(`${base}/validate`,payload)).data;frozen.value={...payload,requestId:uuid(),revision:validation.revision};remember('batch',frozen.value.requestId)}receipt.value=(await Request.post(`${base}/preview`,frozen.value)).data})}
function submit(){return run(async()=>{receipt.value=null;receipt.value=(await Request.post(base,frozen.value)).data;batch.value=(await Request.get(`${base}/batches/${frozen.value.requestId}`)).data;await load()})}
function readBatch(id:string){return run(async()=>{batch.value=(await Request.get(`${base}/batches/${id}`)).data;lookup.value=id;if(frozen.value?.requestId===id)receipt.value=batch.value;exportFrozen.value=null;exportReceipt.value=null})}
function reconcileBatch(id:string){return run(async()=>{receipt.value=(await Request.post(`${base}/batches/${id}/reconcile`)).data;batch.value=(await Request.get(`${base}/batches/${id}`)).data;await load()})}
function readKey(id:number){return run(async()=>{key.value=(await Request.get(`${base}/inventory/${id}`)).data;keyHistory.value=(await Request.get(`${base}/inventory/${id}/history`)).data;keyFrozen.value=null;keyReceipt.value=null})}
function previewKey(operation:string){return run(async()=>{if(!reason.value.trim())throw new Error('请填写停用或恢复原因');if(!keyFrozen.value){keyFrozen.value={requestId:uuid(),revision:key.value.revision,operation,reason:reason.value,...(operation==='resume'?{targetRequestId:key.value.pauseRequestId}:{})};remember('key',`${key.value.id}/${keyFrozen.value.requestId}`)}keyReceipt.value=(await Request.post(`${base}/inventory/${key.value.id}/preview`,keyFrozen.value)).data})}
function saveKey(){return run(async()=>{keyReceipt.value=null;keyReceipt.value=(await Request.post(`${base}/inventory/${key.value.id}`,keyFrozen.value)).data;key.value=(await Request.get(`${base}/inventory/${key.value.id}`)).data;keyHistory.value=(await Request.get(`${base}/inventory/${key.value.id}/history`)).data;await query()})}
function reconcileKey(id:number,requestId:string){return run(async()=>{keyReceipt.value=(await Request.post(`${base}/inventory/${id}/${requestId}/reconcile`)).data;key.value=(await Request.get(`${base}/inventory/${id}`)).data;keyHistory.value=(await Request.get(`${base}/inventory/${id}/history`)).data;await query()})}
function download(){return run(async()=>{if(!exportReason.value.trim())throw new Error('请填写导出原因');if(!exportFrozen.value){exportFrozen.value={requestId:uuid(),revision:batch.value.exportRevision,reason:exportReason.value};remember('export',`${batch.value.requestId}/${exportFrozen.value.requestId}`)}
 const r:any=await Request.post(`${base}/batches/${batch.value.requestId}/export`,exportFrozen.value,{responseType:'blob'});const blob=r.data;if(blob.type.includes('json'))throw new Error('导出未返回CSV，请核对原编号');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`website-cdk-${exportFrozen.value.requestId}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exportReceipt.value={requestId:exportFrozen.value.requestId,state:'PERSISTED',sha256:r.headers?.['x-artifact-sha256']};exports.value=(await Request.get(`${base}/exports/history`)).data
})}
function repeatExport(row:any){return run(async()=>{batch.value=(await Request.get(`${base}/batches/${row.targetKey}`)).data;exportFrozen.value={requestId:row.requestId,revision:row.revision,reason:row.reason};exportReason.value=row.reason;exportReceipt.value=row})}
function reconcileExport(row:any){return run(async()=>{exportReceipt.value=(await Request.post(`${base}/batches/${row.targetKey}/export/${row.requestId}/reconcile`)).data;exports.value=(await Request.get(`${base}/exports/history`)).data})}
onMounted(()=>{lookup.value=sessionStorage.getItem('cdk-inventory-batch')||'';run(load)})
</script>
<template>
<a-space direction="vertical" fill>
 <a-alert>管理网站卡密池。制码不发奖；停用只改变可用状态，不能恢复已使用或结果未知的码。明文卡密仅在明确导出的 CSV 中提供；该 CSV 不是晴空原生配套格式。</a-alert>
 <a-alert v-if="error" type="error">{{error}}</a-alert>
 <a-card title="按批次制码">
  <a-form :model="draft" layout="vertical"><a-space wrap>
   <a-form-item label="奖励类型"><a-select v-model="draft.type" :disabled="busy||!!frozen" style="width:160px"><a-option :value="0">点券</a-option><a-option :value="1">物品（PVF校验）</a-option></a-select></a-form-item>
   <a-form-item label="面值或物品编号"><a-input-number v-model="draft.face" :disabled="busy||!!frozen" :min="1" :precision="0" /></a-form-item>
   <a-form-item label="数量（最多1000）"><a-input-number v-model="draft.count" :disabled="busy||!!frozen" :min="1" :max="1000" :precision="0" /></a-form-item>
   <a-form-item label="显示名称（可留空）"><a-input v-model="draft.faceName" placeholder="卡密显示名称" :disabled="busy||!!frozen" /></a-form-item>
   <a-form-item label="制码原因"><a-input v-model="draft.reason" placeholder="填写制码原因" :disabled="busy||!!frozen" :max-length="100" /></a-form-item>
  </a-space></a-form>
  <a-space wrap><a-button :disabled="busy||!!receipt&&receipt.state!=='PREVIEWED'" @click="prepare">预览制码</a-button><a-button type="primary" :disabled="busy||receipt?.state!=='PREVIEWED'" @click="submit">提交本批制码</a-button><a-button :disabled="busy||!!frozen&&!terminal(receipt)" @click="frozen=null;receipt=null">新建制码批次</a-button><a-button v-if="frozen" :disabled="busy" @click="reconcileBatch(frozen.requestId)">核对本批原编号</a-button></a-space>
  <pre v-if="frozen">操作编号 {{frozen.requestId}}；{{receipt?.state||'响应未知，保留原编号核对'}}</pre>
  <pre v-if="receipt" style="white-space:pre-wrap">{{JSON.stringify(receipt,null,2)}}</pre>
 </a-card>
 <a-space><a-input v-model="lookup" placeholder="按原制码批次编号读取" /><a-button :disabled="busy||!lookup" @click="readBatch(lookup)">读取制码批次</a-button><a-button :disabled="busy" @click="run(load)">刷新管理列表</a-button></a-space>
 <a-table :data="batches" :pagination="false" row-key="requestId"><template #columns><a-table-column title="制码批次" data-index="requestId" /><a-table-column title="状态" data-index="state" /><a-table-column title="操作"><template #cell="{record}"><a-button :disabled="busy" @click="readBatch(record.requestId)">读取</a-button><a-button v-if="record.state==='PREPARED'" :disabled="busy" @click="reconcileBatch(record.requestId)">核对</a-button></template></a-table-column></template></a-table>
 <a-card v-if="batch" title="批次明细与显式导出"><div>{{batch.requestId}} — {{batch.state}}</div><a-alert v-if="batch.exportUnavailableReason" type="warning">{{batch.exportUnavailableReason}}</a-alert><a-space><a-input v-model="exportReason" placeholder="填写明文导出原因" :disabled="busy||!!exportFrozen" /><a-button :disabled="busy||!batch.exportRevision" @click="download">{{exportFrozen?'按原编号重新下载CSV':'导出明文CSV'}}</a-button></a-space><div v-if="exportFrozen">导出编号 {{exportFrozen.requestId}}；{{exportReceipt?.state||'响应未知，请核对导出回执'}}</div><pre style="white-space:pre-wrap">{{JSON.stringify(batch,null,2)}}</pre></a-card>
 <a-divider>卡密元数据（不显示原文）</a-divider>
 <a-space><a-input v-model="exactCode" type="password" placeholder="精确卡密查询（仅POST提交）" /><a-button :disabled="busy" @click="page=1;run(query)">查询卡密元数据</a-button></a-space>
 <a-table :data="keys" :pagination="false" row-key="id"><template #columns><a-table-column title="记录编号" data-index="id" /><a-table-column title="名称" data-index="faceName" /><a-table-column title="面值或物品编号" data-index="face" /><a-table-column title="可用性" data-index="availability" /><a-table-column title="诊断" data-index="nameError" /><a-table-column title="操作"><template #cell="{record}"><a-button :disabled="busy" @click="readKey(record.id)">读取停用管理</a-button></template></a-table-column></template></a-table>
 <a-pagination :current="page" :total="total" :page-size="20" :disabled="busy" @change="(value:number)=>{page=value;run(query)}" />
 <a-card v-if="key" title="定向停用与恢复"><div>记录 {{key.id}} — {{key.availability}}</div><a-input v-model="reason" placeholder="填写停用或恢复原因" :disabled="busy||!!keyFrozen" /><a-space wrap><a-button :disabled="busy||!!keyFrozen||key.availability!=='available'" @click="previewKey('pause')">预览停用</a-button><a-button :disabled="busy||!!keyFrozen||!key.pauseRequestId" @click="previewKey('resume')">预览恢复</a-button><a-button :disabled="busy||keyReceipt?.state!=='PREVIEWED'" @click="saveKey">提交可用性变更</a-button><a-button :disabled="busy||!!keyFrozen&&!terminal(keyReceipt)" @click="keyFrozen=null;keyReceipt=null;reason=''">新建可用性操作</a-button><a-button v-if="keyFrozen" :disabled="busy" @click="reconcileKey(key.id,keyFrozen.requestId)">核对可用性原编号</a-button></a-space><pre v-if="keyFrozen">{{keyFrozen.requestId}} — {{keyReceipt?.state||'响应未知，保留原编号核对'}}</pre><pre style="white-space:pre-wrap">{{JSON.stringify(keyHistory,null,2)}}</pre><a-button v-for="row in keyHistory.filter(r=>r.state==='PREPARED')" :key="row.requestId" :disabled="busy" @click="reconcileKey(key.id,row.requestId)">核对 {{row.requestId}}</a-button></a-card>
 <a-divider>导出回执（最近50条，无卡密原文）</a-divider><a-table :data="exports" :pagination="false" row-key="requestId"><template #columns><a-table-column title="导出编号" data-index="requestId" /><a-table-column title="批次" data-index="targetKey" /><a-table-column title="状态" data-index="state" /><a-table-column title="操作"><template #cell="{record}"><a-button v-if="record.state==='PREPARED'" :disabled="busy" @click="reconcileExport(record)">核对导出原编号</a-button><a-button v-if="record.state==='PERSISTED'" :disabled="busy" @click="repeatExport(record)">读取原导出以重新下载</a-button></template></a-table-column></template></a-table>
</a-space>
</template>
